def body_range(lines, defline):
    """return (start,end) 1-based inclusive of function body given def line (1-based of the identifier line)"""
    # find opening brace from defline forward
    i = defline-1
    n=len(lines)
    depth=0; started=False
    # heuristics: find first '{' after defline; ensure not in same stmt comment
    while i < n:
        if lines[i].startswith("#"):
            i+=1; continue
        if "{" in lines[i]:
            started=True
            depth=lines[i].count("{")-lines[i].count("}")
            break
        if ";" in lines[i] and not lines[i].strip().startswith("*") and "=" not in lines[i]:
            # declaration only
            return None
        i+=1
        if i-defline > 8: return None
    if not started: return None
    start=i
    while i < n:
        depth += lines[i].count("{")-lines[i].count("}")
        if i>start and depth<=0:
            return (defline, i+1)
        i+=1
    return (defline, n)

